item.content:encoded:
/* === GLOBAL FONT & WARNA === */
body {
  font-family: 'Georgia', serif;
  background: #f8f9fa;
  color: #333;
}

/* === JUDUL ARTIKEL === */
.entry-title {
  font-size: 28px;
  font-weight: bold;
  color: #0a3d62;
  text-align: center;
}

/* === META (AUTHOR, DATE) === */
.entry-meta {
  font-size: 13px;
  color: #777;
  text-align: center;
  margin-bottom: 20px;
}

/* === KONTEN ARTIKEL === */
.entry-content {
  font-size: 16px;
  line-height: 1.8;
  text-align: justify;
}

/* === LINK DALAM ARTIKEL === */
.entry-content a {
  color: #1e90ff;
  text-decoration: none;
}
.entry-content a:hover {
  text-decoration: underline;
}

/* === BOX ARTIKEL (CARD STYLE) === */
.post {
  background: #fff;
  padding: 25px;
  border-radius: 8px;
  box-shadow: 0 4px 10px rgba(0,0,0,0.05);
  margin-bottom: 30px;
}

/* === BUTTON DOWNLOAD PDF === */
a.pdf-download {
  display: inline-block;
  background: #27ae60;
  color: #fff;
  padding: 10px 15px;
  border-radius: 5px;
  margin-top: 10px;
}
a.pdf-download:hover {
  background: #1e8449;
}

/* === HEADER === */
.site-header {
  background: #0a3d62;
}
.site-title a {
  color: #fff;
  font-weight: bold;
}

/* === FOOTER === */
.site-footer {
  background: #0a3d62;
  color: #fff;
  text-align: center;
  padding: 20px;
}
